// ======== FILL THESE IN ========
// From GET https://zernio.com/api/v1/accounts  (accounts[]._id)
const ZERNIO_X_ACCOUNT_ID  = 'PASTE_X_ACCOUNT_ID';
const ZERNIO_FB_ACCOUNT_ID = 'PASTE_FACEBOOK_ACCOUNT_ID';
const SITE = 'https://www.5talentsmag.com';
// ===============================

const out = [];

for (const item of $input.all()) {
  // Sanity posts the projection as the request body.
  const b = item.json.body ?? item.json;

  const title   = String(b.title   || '').trim();
  const deck    = String(b.deck    || '').trim();
  const slug    = String(b.slug    || '').trim();
  const section = String(b.section || 'current').trim();
  const id      = String(b._id || slug);

  // No headline or no slug means the document is not ready to announce.
  if (!title || !slug) continue;

  const url = `${SITE}/${section}/${slug}?utm_source=social&utm_medium=organic&utm_campaign=auto-announce`;

  // X counts every link as 23 characters regardless of its real length.
  const LINK_COST = 23;
  const room = 280 - LINK_COST - 2;
  const xTitle = title.length > room
    ? title.slice(0, room - 1).trimEnd() + '\u2026'
    : title;
  const xText = `${xTitle}\n\n${url}`;

  // Facebook has room for the deck as well.
  const fbText = deck
    ? `${title}\n\n${deck}\n\n${url}`
    : `${title}\n\n${url}`;

  out.push({
    json: {
      articleId: id,
      title,
      deck,
      url,
      xText,
      fbText,
      xAccountId: ZERNIO_X_ACCOUNT_ID,
      fbAccountId: ZERNIO_FB_ACCOUNT_ID
    }
  });
}

return out;
